using System.Net;
using System.Text;
using System.Text.Json.Nodes;
using Microsoft.Extensions.Caching.Memory;
namespace SydneyBuddy.Api.Tests;
public sealed class PoiTests {
    sealed class FakeProvider:IPoiProvider {public int Calls;public Task<JsonArray> SearchAsync(double lat,double lng,int radius,string category,string text,CancellationToken token){Calls++;return Task.FromResult(new JsonArray(new JsonObject{["id"]="osm:node:1"}));}}
    sealed class Handler:HttpMessageHandler {public string? Body;protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){Body=await request.Content!.ReadAsStringAsync(token);return new(HttpStatusCode.OK){Content=new StringContent("""{"elements":[{"type":"way","id":123,"center":{"lat":-33.86,"lon":151.21},"tags":{"name":"Native cafe","name:zh":"中文咖啡館","name:en":"Test Cafe","description:zh":"中文介紹","description:en":"An English cafe description","amenity":"cafe","opening_hours":"Mo-Fr 09:00-17:00"}},{"type":"node","id":124,"lat":0,"lon":0,"tags":{"name":"Outside Sydney"}}]}""",Encoding.UTF8,"application/json")};}}
    [Fact]public async Task NormalizesWayCentersAndPreservesUnknownPriceAndOpeningText(){var handler=new Handler();var points=await new OsmPoiProvider(new HttpClient(handler)).SearchAsync(-33.86,151.21,1500,"food","",default);Assert.Single(points);var p=points[0]!.AsObject();Assert.Equal("osm:way:123",p.Str("id"));Assert.Equal("cafe",p.Str("poiKind"));Assert.Equal("Test Cafe",p.Str("name"));Assert.Equal("An English cafe description",p.Str("description"));Assert.Equal("Mo-Fr 09:00-17:00",p.Str("openingHoursText"));Assert.Null(p["openMinute"]);Assert.Contains("unknown",p.Str("note"));Assert.Contains("around",handler.Body!);}
    [Fact]public async Task CachesIdenticalQueriesAndRejectsInvalidAreas(){using var cache=new MemoryCache(new MemoryCacheOptions());var provider=new FakeProvider();var service=new PoiService(provider,cache);var input=new JsonObject{["lat"]=-33.86,["lng"]=151.21,["category"]="food"};await service.SearchAsync(input,default);await service.SearchAsync(input,default);Assert.Equal(1,provider.Calls);input["lat"]=0;await Assert.ThrowsAsync<ServiceException>(()=>service.SearchAsync(input,default));}
    [Fact]public async Task UnknownProviderNeverFallsBackToOsm(){using var cache=new MemoryCache(new MemoryCacheOptions());var provider=new FakeProvider();var service=new PoiService(provider,cache);await Assert.ThrowsAsync<ServiceException>(()=>service.SearchAsync(new(){["provider"]="apple"},default));Assert.Equal(0,provider.Calls);}
    [Fact]public void AppleImportedPoiKeepsSourceAndUnknownCosts(){var point=PoiService.Import(new(){["id"]="apple:test123",["source"]="Apple Maps",["name"]="Cafe",["lat"]=-33.86,["lng"]=151.21,["cost"]=99,["openMinute"]=0,["category"]="美食"});Assert.Equal("Apple Maps",point.Str("source"));Assert.Equal("meal",PoiService.ActivityKind(point));Assert.Equal(0,point.Int("cost"));Assert.Null(point["openMinute"]);Assert.Throws<ServiceException>(()=>PoiService.Import(new(){["id"]="apple:test123",["name"]="Untrusted",["lat"]=-33.86,["lng"]=151.21}));}
    [Fact]public void UserTextCannotInjectOverpassClauses(){var q=OsmPoiProvider.Query(-33.86,151.21,500,"food","a\";out;(");Assert.Contains("\\\"",q);Assert.EndsWith(");out center 120;",q);Assert.Contains("[timeout:20]",q);}
    [Fact]public void ImportedPoiCannotClaimKnownOpeningHoursOrPrice(){var point=PoiService.Import(new(){["id"]="osm:node:12",["name"]="Cafe",["lat"]=-33.86,["lng"]=151.21,["cost"]=99,["openMinute"]=0,["closeMinute"]=1440});Assert.Equal(0,point.Int("cost"));Assert.Null(point["openMinute"]);Assert.Throws<ServiceException>(()=>PoiService.Import(new(){["id"]="invalid"}));}
    [Theory][InlineData("osm:node:123","OpenStreetMap")][InlineData("apple:test123","Apple Maps")][InlineData("overture:00000000-0000-4000-8000-000000000001","Overture Maps")]public void ImportedPoiCanBeScheduledAndRestoredWithoutLiveLookup(string id,string source){using var cache=new CatalogCache();var editor=new ScheduleEditorService(new PlaceCatalog(cache,new ProjectPaths(TestSupport.RepositoryRoot())));var trip=editor.Build(new(){["trip"]=new JsonObject{["mode"]="demo",["title"]="POI test",["profile"]=TestSupport.Profile(1)}});var s=trip.Object("schedule")!;s.Array("candidates")!.Add(PoiService.Import(new(){["id"]=id,["source"]=source,["name"]="Cafe",["lat"]=-33.86,["lng"]=151.21,["category"]="美食",["poiKind"]="cafe"}));var days=(JsonArray)s.Array("days")!.DeepClone();days[0]!.Array("activities")!.Add(new JsonObject{["id"]="new-poi",["kind"]="meal",["placeId"]=id,["duration"]=30});var result=editor.Build(new(){["trip"]=trip,["days"]=days});var updated=result.Object("schedule")!;Assert.Contains(updated.Array("issues")!.OfType<JsonObject>(),i=>i.Str("code")=="poi-unknown");Assert.Contains(updated.Array("days")![0]!.Array("activities")!.OfType<JsonObject>(),a=>a.Str("placeId")==id&&!a.Bool("hoursVerified"));}
}
